 /** Parse a URL query string. See README.md for the rules. */
 export function parseQuery(query: string): Query {
-  throw new Error("not implemented");
+  const result: Query = {};
+
+  const raw = query.startsWith("?") ? query.slice(1) : query;
+  if (raw === "") {
+    return result;
+  }
+
+  const decodePart = (part: string): string => {
+    const withSpaces = part.replace(/\+/g, " ");
+
+    try {
+      return decodeURIComponent(withSpaces);
+    } catch {
+      return withSpaces;
+    }
+  };
+
+  for (const pair of raw.split("&")) {
+    if (pair === "") {
+      continue;
+    }
+
+    const separator = pair.indexOf("=");
+    const keyPart = separator === -1 ? pair : pair.slice(0, separator);
+    const valuePart = separator === -1 ? "" : pair.slice(separator + 1);
+
+    const key = decodePart(keyPart);
+    const value = decodePart(valuePart);
+    const previous = result[key];
+
+    if (previous === undefined) {
+      result[key] = value;
+    } else if (Array.isArray(previous)) {
+      previous.push(value);
+    } else {
+      result[key] = [previous, value];
+    }
+  }
+
+  return result;
 }
